  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Arpenteur-De-Monde-(Druide).html&quot; title=&quot;Arpenteur de monde&quot;&gt;Arpenteur de monde&lt;/a&gt; (AG)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Aspirant-Naga-(Druide).html&quot; title=&quot;Aspirant naga&quot;&gt;Aspirant naga&lt;/a&gt; (&lt;a class=&quot;pagelink&quot; href=&quot;Nagaji-(Race).html&quot; title=&quot;Les nagajis&quot;&gt;nagaji&lt;/a&gt;) (MR)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Chamanes-Animaux-(Druide).html&quot; title=&quot;Chamanes animaux&quot;&gt;Chamanes animaux&lt;/a&gt; (MJRA,AG,AM)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Changepeau-(Druide).html&quot; title=&quot;Changepeau&quot;&gt;Changepeau&lt;/a&gt; (&lt;i&gt;UI&lt;/i&gt;)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Chanteur-Sylvestre-(Druide).html&quot; title=&quot;Chanteur sylvestre&quot;&gt;Chanteur sylvestre&lt;/a&gt; (&lt;a class=&quot;pagelink&quot; href=&quot;Elfe.html&quot; title=&quot;Les elfes&quot;&gt;Elfe&lt;/a&gt;) (MR)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Chuchoteur-Sauvage-(Druide).html&quot; title=&quot;Chuchoteur sauvage&quot;&gt;Chuchoteur sauvage&lt;/a&gt; (MCA)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Croc-De-La-Nature-(Druide).html&quot; title=&quot;Croc de la nature&quot;&gt;Croc de la nature&lt;/a&gt; (MCA) &lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Druide-Aquatique-(Druide).html&quot; title=&quot;Druide aquatique&quot;&gt;Druide aquatique&lt;/a&gt; (MJRA)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Druide-Arctique-(Druide).html&quot; title=&quot;Druide arctique&quot;&gt;Druide arctique&lt;/a&gt; (MJRA)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Druide-De-La-Jungle-(Druide).html&quot; title=&quot;Druide de la jungle&quot;&gt;Druide de la jungle&lt;/a&gt; (MJRA)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Druide-Des-Cavernes-(Druide).html&quot; title=&quot;Druide des cavernes&quot;&gt;Druide des cavernes&lt;/a&gt; (MJRA)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Druide-Des-D&#233;serts-(Druide).html&quot; title=&quot;Druide des d&#233;serts&quot;&gt;Druide des d&#233;serts&lt;/a&gt; (MJRA)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Druide-Des-Marais-(Druide).html&quot; title=&quot;Druide des marais&quot;&gt;Druide des marais&lt;/a&gt; (MJRA)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Druide-Des-Montagnes-(Druide).html&quot; title=&quot;Druide des montagnes&quot;&gt;Druide des montagnes&lt;/a&gt; (MJRA)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Druide-Des-Ouragans-(Druide).html&quot; title=&quot;Druide des ouragans&quot;&gt;Druide des ouragans&lt;/a&gt; (MMI)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Druide-Des-Plaines-(Druide).html&quot; title=&quot;Druide des plaines&quot;&gt;Druide des plaines&lt;/a&gt; (MJRA)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Druide-Des-Temp&#234;tes-(Druide).html&quot; title=&quot;Druide des temp&#234;tes&quot;&gt;Druide des temp&#234;tes&lt;/a&gt; (AM)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Druide-Du-Ciel-(Druide).html&quot; title=&quot;Druide du ciel&quot;&gt;Druide du ciel&lt;/a&gt; (&lt;a class=&quot;pagelink&quot; href=&quot;Sylphe-(Race).html&quot; title=&quot;Les sylphes&quot;&gt;Sylphe&lt;/a&gt;) (MR)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Druide-R&#233;incarn&#233;-(Druide).html&quot; title=&quot;Druide r&#233;incarn&#233;&quot;&gt;Druide r&#233;incarn&#233;&lt;/a&gt; (AM)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Druide-Urbain-(Druide).html&quot; title=&quot;Druide urbain&quot;&gt;Druide urbain&lt;/a&gt; (MJRA)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Enfant-De-La-Lune-(Druide).html&quot; title=&quot;Enfant de la lune&quot;&gt;Enfant de la lune&lt;/a&gt; (AM)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Enfant-Sauvage-(Druide).html&quot; title=&quot;Enfant sauvage&quot;&gt;Enfant sauvage&lt;/a&gt; (&lt;a class=&quot;pagelink&quot; href=&quot;Humain.html&quot; title=&quot;Les humains&quot;&gt;Humain&lt;/a&gt;) (MR)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Fl&#233;trisseur-(Druide).html&quot; title=&quot;Fl&#233;trisseur&quot;&gt;Fl&#233;trisseur&lt;/a&gt; (MJRA)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Gardien-Antique-(Druide).html&quot; title=&quot;Gardien antique&quot;&gt;Gardien antique&lt;/a&gt; (&lt;a class=&quot;pagelink&quot; href=&quot;Homme-Serpent.html&quot; title=&quot;Homme-serpent&quot;&gt;Homme-serpent&lt;/a&gt;) (CM)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;M&#233;tamorphe-Sauvage-(Druide).html&quot; title=&quot;M&#233;tamorphe sauvage&quot;&gt;M&#233;tamorphe sauvage&lt;/a&gt; (MCA)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Sage-Des-Menhirs-(Druide).html&quot; title=&quot;Sage des menhirs&quot;&gt;Sage des menhirs&lt;/a&gt; (AM)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Seigneur-De-La-Meute-(Druide).html&quot; title=&quot;Seigneur de la meute&quot;&gt;Seigneur de la meute&lt;/a&gt; (AM)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Surnaturaliste-(Druide).html&quot; title=&quot;Surnaturaliste&quot;&gt;Surnaturaliste&lt;/a&gt; (&lt;i&gt;OO&lt;/i&gt;)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Troll-Furieux-(Druide).html&quot; title=&quot;Troll furieux&quot;&gt;Troll furieux&lt;/a&gt; (&lt;a class=&quot;pagelink&quot; href=&quot;Troll.html&quot; title=&quot;Troll&quot;&gt;Troll&lt;/a&gt;) (CM)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Urushiol-(Druide).html&quot; title=&quot;Urushiol&quot;&gt;Urushiol&lt;/a&gt; (&lt;i&gt;UI&lt;/i&gt;)&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;&lt;a href=&quot;/Wiki/Pathfinder-RPG.Manuel des joueurs - R&#232;gles avanc&#233;es (Contenu).ashx&quot; style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Advanced Player&#39;s Guide/Manuel des joueurs - R&#232;gles avanc&#233;es&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoAPG.gif&quot; style=&quot;opacity: 0.7&quot; loop=&quot;infinite&quot; /&gt;
&lt;/a&gt;&lt;i&gt;Bergers des lacs et des rivi&#232;res, le druide aquatique veille sur les &#233;tendues d’eau. Des rivi&#232;res peu profondes aux fosses des oc&#233;ans, il s’occupe de leurs habitants et communie avec les flots.&lt;/i&gt;&lt;br /&gt;&lt;br /&gt;&lt;h3 class=&quot;separator&quot;&gt;Empathie sauvage (Ext)&lt;a class=&quot;headeranchor&quot; id=&quot;Empathie_sauvage_Ext_0&quot; href=&quot;#Empathie_sauvage_Ext_0&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Cette aptitude ne marche qu’avec les cr&#233;atures qui ont une &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Vitessededeplacement.html&quot; title=&quot;VD&quot;&gt;vitesse de d&#233;placement&lt;/a&gt; dans l’eau ou qui poss&#232;dent le &lt;a class=&quot;pagelink&quot; href=&quot;Sous-Types-De-Cr&#233;atures.html&quot; title=&quot;Les sous-types de cr&#233;atures&quot;&gt;sous-type&lt;/a&gt; &lt;a class=&quot;pagelink&quot; href=&quot;Sous-Type-Aquatique.html&quot; title=&quot;Aquatique (sous-type)&quot;&gt;aquatique&lt;/a&gt; ou &lt;a class=&quot;pagelink&quot; href=&quot;Sous-Type-Eau.html&quot; title=&quot;Eau (sous-type)&quot;&gt;Eau&lt;/a&gt;. Le &lt;a class=&quot;pagelink&quot; href=&quot;Druide.html&quot; title=&quot;Le druide&quot;&gt;druide&lt;/a&gt; peut cependant am&#233;liorer l’attitude de celles ayant une &lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques#Intelligence.html&quot; title=&quot;L&amp;#39;Intelligence&quot;&gt;Intelligence&lt;/a&gt; de 2 ou moins, y compris celles d&#233;nu&#233;es d’&lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques#Intelligence.html&quot; title=&quot;L&amp;#39;Intelligence&quot;&gt;intelligence&lt;/a&gt;, et ce quel que soit le &lt;a class=&quot;pagelink&quot; href=&quot;Types-De-Cr&#233;atures.html&quot; title=&quot;Les types et sous type de cr&#233;atures&quot;&gt;type&lt;/a&gt; de ces cr&#233;atures.&lt;br /&gt;&lt;br /&gt;&lt;h3 class=&quot;separator&quot;&gt;Adaptation &#224; l’eau (Ext)&lt;a class=&quot;headeranchor&quot; id=&quot;Adaptation_&#224;_l’eau_Ext_1&quot; href=&quot;#Adaptation_&#224;_l’eau_Ext_1&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Au &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Niveau.html&quot; title=&quot;niveau&quot;&gt;niveau&lt;/a&gt; 2 et lorsqu’il se trouve en terrain aquatique, le personnage re&#231;oit un bonus d’intuition &#233;gal &#224; la moiti&#233; de son niveau de &lt;a class=&quot;pagelink&quot; href=&quot;Druide.html&quot; title=&quot;Le druide&quot;&gt;druide&lt;/a&gt; sur ses jets d’&lt;a class=&quot;pagelink&quot; href=&quot;D&#233;roulement-Dun-Combat#Initiative.html&quot; title=&quot;initiative&quot;&gt;initiative&lt;/a&gt;, ses &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Jettest.html&quot; title=&quot;test&quot;&gt;tests&lt;/a&gt; de &lt;a class=&quot;pagelink&quot; href=&quot;Connaissances.html&quot; title=&quot;Connaissances&quot;&gt;Connaissances&lt;/a&gt; (g&#233;ographie), &lt;a class=&quot;pagelink&quot; href=&quot;Discr&#233;tion.html&quot; title=&quot;Discr&#233;tion&quot;&gt;Discr&#233;tion&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Natation.html&quot; title=&quot;Natation&quot;&gt;Natation&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Perception.html&quot; title=&quot;Perception&quot;&gt;Perception&lt;/a&gt; et &lt;a class=&quot;pagelink&quot; href=&quot;Survie.html&quot; title=&quot;Survie&quot;&gt;Survie&lt;/a&gt;. Il est impossible de le pister dans de tels environnements. Cette capacit&#233; remplace &lt;a class=&quot;pagelink&quot; href=&quot;Druide.html#DEPLACEMENTFACILITE&quot; title=&quot;Le druide&quot;&gt;d&#233;placement facilit&#233;&lt;/a&gt;.&lt;br /&gt;&lt;br /&gt;&lt;h3 class=&quot;separator&quot;&gt;Nageur inn&#233; (Ext)&lt;a class=&quot;headeranchor&quot; id=&quot;Nageur_inn&#233;_Ext_2&quot; href=&quot;#Nageur_inn&#233;_Ext_2&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Au &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Niveau.html&quot; title=&quot;niveau&quot;&gt;niveau&lt;/a&gt; 3, le personnage a une vitesse de &lt;a class=&quot;pagelink&quot; href=&quot;D&#233;placements.html&quot; title=&quot;Les d&#233;placements&quot;&gt;d&#233;placement&lt;/a&gt; dans l’eau &#233;gale &#224; la moiti&#233; de sa &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Vitessededeplacement.html&quot; title=&quot;VD&quot;&gt;vitesse de d&#233;placement&lt;/a&gt; sur terre. Cette capacit&#233; remplace &lt;a class=&quot;pagelink&quot; href=&quot;Druide.html#ABSENCEDETRACES&quot; title=&quot;Le druide&quot;&gt;absence de traces&lt;/a&gt;.&lt;br /&gt;&lt;br /&gt;&lt;h3 class=&quot;separator&quot;&gt;R&#233;sistance &#224; la fureur des oc&#233;ans (Ext)&lt;a class=&quot;headeranchor&quot; id=&quot;R&#233;sistance_&#224;_la_fureur_des_oc&#233;ans_Ext_3&quot; href=&quot;#R&#233;sistance_&#224;_la_fureur_des_oc&#233;ans_Ext_3&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Au niveau 4, le &lt;a class=&quot;pagelink&quot; href=&quot;Druide.html&quot; title=&quot;Le druide&quot;&gt;druide&lt;/a&gt; aquatique b&#233;n&#233;ficie d’un bonus de +4 sur ses &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Jetdesauvegarde.html&quot; title=&quot;jet de sauvegarde&quot;&gt;jets de sauvegarde&lt;/a&gt; contre les sorts qui utilisent ou qui ciblent l’eau, ou contre les capacit&#233;s exceptionnelles et les pouvoirs surnaturels des cr&#233;atures poss&#233;dant le &lt;a class=&quot;pagelink&quot; href=&quot;Sous-Types-De-Cr&#233;atures.html&quot; title=&quot;Les sous-types de cr&#233;atures&quot;&gt;sous-type&lt;/a&gt; &lt;a class=&quot;pagelink&quot; href=&quot;Sous-Type-Aquatique.html&quot; title=&quot;Aquatique (sous-type)&quot;&gt;aquatique&lt;/a&gt; ou &lt;a class=&quot;pagelink&quot; href=&quot;Sous-Type-Eau.html&quot; title=&quot;Eau (sous-type)&quot;&gt;Eau&lt;/a&gt;. Cette capacit&#233; remplace &lt;a class=&quot;pagelink&quot; href=&quot;Druide.html#RESISTANCEALAPPELDELANATURE&quot; title=&quot;Le druide&quot;&gt;r&#233;sistance &#224; l’appel de la nature&lt;/a&gt;.&lt;br /&gt;&lt;br /&gt;&lt;h3 class=&quot;separator&quot;&gt;Forme animale (Ext)&lt;a class=&quot;headeranchor&quot; id=&quot;Forme_animale_Ext_4&quot; href=&quot;#Forme_animale_Ext_4&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Un &lt;a class=&quot;pagelink&quot; href=&quot;Druide.html&quot; title=&quot;Le druide&quot;&gt;druide&lt;/a&gt; des eaux re&#231;oit cette aptitude au niveau 6 et son niveau effectif sera &#233;gal &#224; son niveau de &lt;a class=&quot;pagelink&quot; href=&quot;Druide.html&quot; title=&quot;Le druide&quot;&gt;druide&lt;/a&gt; -2.&lt;br /&gt;&lt;br /&gt;&lt;h3 class=&quot;separator&quot;&gt;N&#233; de la mer (Ext)&lt;a class=&quot;headeranchor&quot; id=&quot;N&#233;_de_la_mer_Ext_5&quot; href=&quot;#N&#233;_de_la_mer_Ext_5&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Au niveau 9, le personnage re&#231;oit le &lt;a class=&quot;pagelink&quot; href=&quot;Sous-Type-Aquatique.html&quot; title=&quot;Aquatique (sous-type)&quot;&gt;sous-type aquatique&lt;/a&gt;, la caract&#233;ristique raciale &lt;a class=&quot;pagelink&quot; href=&quot;Amphibie-(Capacit&#233;).html&quot; title=&quot;Amphibie&quot;&gt;amphibie&lt;/a&gt; et une &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Vitessededeplacement.html&quot; title=&quot;VD&quot;&gt;vitesse de d&#233;placement&lt;/a&gt; dans l’eau &#233;gale &#224; sa &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Vitessededeplacement.html&quot; title=&quot;VD&quot;&gt;vitesse de d&#233;placement&lt;/a&gt; sur terre. Il peut &#233;galement r&#233;sister aux effets du froid naturel comme avec &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Endurance-Aux-&#201;nergies-Destructives.html&quot; title=&quot;Endurance aux &#233;nergies destructives&quot;&gt;endurance aux &#233;nergies destructives&lt;/a&gt;&lt;/i&gt;. Cette capacit&#233; remplace &lt;a class=&quot;pagelink&quot; href=&quot;Druide.html#IMMUNITECONTRELEVENIN&quot; title=&quot;Le druide&quot;&gt;immunit&#233;s contre le venin&lt;/a&gt;.&lt;br /&gt;&lt;br /&gt;
&lt;h3 class=&quot;separator&quot;&gt;Plong&#233;e profonde (Ext)&lt;a class=&quot;headeranchor&quot; id=&quot;Plong&#233;e_profonde_Ext_6&quot; href=&quot;#Plong&#233;e_profonde_Ext_6&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Au niveau 13, le personnage re&#231;oit une &lt;a class=&quot;pagelink&quot; href=&quot;R&#233;duction-De-D&#233;g&#226;ts-(Capacit&#233;).html&quot; title=&quot;RD&quot;&gt;RD&lt;/a&gt;/tranchante ou perforante &#233;gale &#224; la moiti&#233; de son niveau de druide. Cette &lt;a class=&quot;pagelink&quot; href=&quot;R&#233;duction-De-D&#233;g&#226;ts-(Capacit&#233;).html&quot; title=&quot;r&#233;duction des d&#233;g&#226;ts&quot;&gt;r&#233;duction des d&#233;g&#226;ts&lt;/a&gt; s’applique aussi contre les sorts et les &lt;a class=&quot;pagelink&quot; href=&quot;Capacit&#233;s-Sp&#233;ciales.html#TYPES&quot; title=&quot;Les capacit&#233;s sp&#233;ciales&quot;&gt;pouvoirs magiques&lt;/a&gt; qui infligent des dommages en agrippant ou en broyant (par exemple &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Main-Broyeuse.html&quot; title=&quot;Main broyeuse&quot;&gt;main broyeuse&lt;/a&gt;&lt;/i&gt; ou &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Tentacules-Noirs.html&quot; title=&quot;Tentacules noirs&quot;&gt;tentacules noirs&lt;/a&gt;&lt;/i&gt;). Il est insensible &#224; la pression des profondeurs. Cette capacit&#233; remplace &lt;a class=&quot;pagelink&quot; href=&quot;Druide.html#MILLEVISAGES&quot; title=&quot;Le druide&quot;&gt;mille visages&lt;/a&gt;.
